class Solution:
    def minOperations(self, k: int) -> int:
        if k == 1:
            return 0

        min_ops = float('inf')

        for d in range(0, k):
            copies = d + 1
            v = math.ceil(k / copies)
            ops = (v - 1) + d
            min_ops = min(min_ops, ops)

        return min_ops

def main():
