class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        uf = UnionFind(n)
        prime_to_idx = {}

        for i, num in enumerate(nums):
            temp = num
            d = 2
            while d * d <= temp:
                if temp % d == 0:
                    if d in prime_to_idx:
                        uf.union(i, prime_to_idx[d])
                    else:
                        prime_to_idx[d] = i
                    while temp % d == 0:
                        temp //= d
                d += 1
            if temp > 1:
                if temp in prime_to_idx:
                    uf.union(i, prime_to_idx[temp])
                else:
                    prime_to_idx[temp] = i

        root = uf.find(0)
        return all(uf.find(i) == root for i in range(n))

def main():
    input_data = sys.stdin.read().split()
    nums = list(map(int, input_data))
    sol = Solution()
    print(sol.canTraverseAllPairs(nums))

main()

