class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        total_and = nums[0]
        for x in nums:
            total_and &= x

        if total_and > 0:
            return 1

        # total_and == 0, greedily split into subarrays with AND = 0
        count = 0
        current_and = (1 << 20) - 1  # all bits set
        for x in nums:
            current_and &= x
            if current_and == 0:
                count += 1
                current_and = (1 << 20) - 1

        return max(count, 1)

