def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N, M = int(input_data[idx]), int(input_data[idx+1])
    idx += 2
    L = [int(input_data[idx+i]) for i in range(N)]
    idx += N

    def can_fit(W):
        # Check if we can fit all words in M lines with window width W
        lines = 1
        current_width = 0
        for i, w in enumerate(L):
            if w > W:
                return False
            if current_width == 0:
                current_width = w
            elif current_width + 1 + w <= W:
                current_width += 1 + w
            else:
                lines += 1
                if lines > M:
                    return False
                current_width = w
        return True

    # Binary search on W
    lo = max(L)  # minimum possible width
    hi = sum(L) + N - 1  # maximum (all on one line)

    while lo < hi:
        mid = (lo + hi) // 2
        if can_fit(mid):
            hi = mid
        else:
            lo = mid + 1

    print(lo)

