def minPath(grid, k):
    n = len(grid)

    # Find the position of each value
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # Find the minimum neighbor value for each cell
    def min_neighbor(i, j):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        min_val = float('inf')
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                min_val = min(min_val, grid[ni][nj])
        return min_val

    # For each starting cell, find the minimum path of length k greedily
    # The minimum path starts from the cell with value 1
    # because 1 is the smallest value possible

    best = None

    for i in range(n):
        for j in range(n):
            # Try starting from each cell
            path = [grid[i][j]]
            ci, cj = i, j
            for step in range(1, k):
                directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
                min_val = float('inf')
                for di, dj in directions:
                    ni, nj = ci + di, cj + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        min_val = min(min_val, grid[ni][nj])
                path.append(min_val)
                # Move to the cell with min_val
                for di, dj in directions:
                    ni, nj = ci + di, cj + dj
                    if 0 <= ni < n and 0 <= nj < n and grid[ni][nj] == min_val:
                        ci, cj = ni, nj
                        break

            if best is None or path < best:
                best = path

    return best

