def solve():
    N, X, K = map(int, input().split())

    def count_at_depth(v, d):
        if d < 0 or v < 1:
            return 0
        if d >= 63:
            # v << d might overflow conceptually but Python handles big ints
            lo = v << d
            if lo > N:
                return 0
            hi = ((v + 1) << d) - 1
            return min(hi, N) - lo + 1
        lo = v << d
        if lo > N:
            return 0
        hi = ((v + 1) << d) - 1
        return min(hi, N) - lo + 1

    ans = 0
    ancestor = X
    for up in range(K + 1):
        down = K - up
        if up == 0:
            ans += count_at_depth(ancestor, down)
        else:
            child = X >> (up - 1)
            ans += count_at_depth(ancestor, down) - count_at_depth(child, down - 1)

        ancestor >>= 1
        if ancestor == 0:
            break

    print(ans)

