class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        b = [nums[i] - i for i in range(n)]

        sorted_b = sorted(set(b))
        rank = {v: i+1 for i, v in enumerate(sorted_b)}
        m = len(sorted_b)

        bit = [-float('inf')] * (m + 2)

        def update(pos, val):
            while pos <= m:
                if bit[pos] < val:
                    bit[pos] = val
                pos += pos & (-pos)

        def query(pos):
            res = -float('inf')
            while pos > 0:
                if bit[pos] > res:
                    res = bit[pos]
                pos -= pos & (-pos)
            return res

        ans = -float('inf')
        for i in range(n):
            r = rank[b[i]]
            prev_max = query(r)
            if prev_max <= 0:
                dp_i = nums[i]
            else:
                dp_i = prev_max + nums[i]
            ans = max(ans, dp_i)
            update(r, dp_i)

        return ans

def main():
    input_data = sys.stdin.read().split()
    nums = list(map(int, input_data))
    sol = Solution()
    print(sol.maxBalancedSubsequenceSum(nums))

