class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        # Find the longest common prefix of all three strings
        min_len = min(len(s1), len(s2), len(s3))

        # Find length of longest common prefix
        lcp = 0
        for i in range(min_len):
            if s1[i] == s2[i] == s3[i]:
                lcp += 1
            else:
                break

        if lcp == 0:
            return -1

        # Number of operations needed
        return (len(s1) - lcp) + (len(s2) - lcp) + (len(s3) - lcp)


