def solve():
    data = sys.stdin.read().split()
    s = data[0]
    k = int(data[1])
    n = len(s)

    INF = float('inf')

    # Precompute cost[i][j] = min changes to make s[i..j] (inclusive) a semi-palindrome
    cost = [[INF]*n for _ in range(n)]

    for i in range(n):
        for j in range(i+1, n):
            L = j - i + 1
            substr = s[i:j+1]
            min_cost = INF
            for d in range(1, L):
                if L % d == 0:
                    total = 0
                    for r in range(d):
                        group = [substr[idx] for idx in range(r, L, d)]
                        g = len(group)
                        changes = sum(1 for p in range(g//2) if group[p] != group[g-1-p])
                        total += changes
                    min_cost = min(min_cost, total)
            cost[i][j] = min_cost

    # dp[parts][end] = min cost to partition s[0:end] into 'parts' semi-palindromes
    dp = [[INF]*(n+1) for _ in range(k+1)]
    dp[0][0] = 0

    for parts in range(1, k+1):
        for end in range(parts, n+1):
            for start in range(parts-1, end):
                if dp[parts-1][start] != INF and end - start >= 2:
                    c = cost[start][end-1]
                    if c != INF:
                        val = dp[parts-1][start] + c
                        if val < dp[parts][end]:
                            dp[parts][end] = val

    print(dp[k][n])

