def fib4(n: int):
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0
    a, b, c, d = 0, 0, 2, 0
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d

from collections import Counter

def solve():
    S = input().strip()
    T = input().strip()

    atcoder = set('atcoder')

    s_counts = Counter(c for c in S if c != '@')
    t_counts = Counter(c for c in T if c != '@')
    s_wild = S.count('@')
    t_wild = T.count('@')

    # Non-atcoder characters must match exactly
    all_chars = set(s_counts.keys()) | set(t_counts.keys())
    for c in all_chars:
        if c not in atcoder:
            if s_counts[c] != t_counts[c]:
                print("No")
                return

    # For atcoder characters, compute deficit on each side
    s_deficit = 0
    t_deficit = 0

    for c in atcoder:
        diff = t_counts[c] - s_counts[c]
        if diff > 0:
            s_deficit += diff
        else:
            t_deficit += (-diff)

    if s_deficit <= s_wild and t_deficit <= t_wild and s_wild - s_deficit == t_wild - t_deficit:
        print("Yes")
    else:
        print("No")

