class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)

        def solve(swapped_last):
            ops = 0
            if swapped_last:
                ops = 1
                m1 = nums2[n-1]
                m2 = nums1[n-1]
            else:
                m1 = nums1[n-1]
                m2 = nums2[n-1]

            for i in range(n-1):
                a, b = nums1[i], nums2[i]
                no_swap_ok = (a <= m1 and b <= m2)
                swap_ok = (b <= m1 and a <= m2)

                if no_swap_ok:
                    pass
                elif swap_ok:
                    ops += 1
                else:
                    return float('inf')

            return ops

        res = min(solve(False), solve(True))
        return res if res != float('inf') else -1

