class Solution:
    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        def count_bits(n):
            if n <= 0: return 0
            result = 0
            for b in range(50):
                result += (n >> (b+1)) * (1 << b) + max(0, (n % (1 << (b+1))) - (1 << b) + 1)
            return result

        def find_kth(k):
            lo, hi = 1, 10**16
            while lo < hi:
                mid = (lo + hi) // 2
                if count_bits(mid) > k:
                    hi = mid
                else:
                    lo = mid + 1
            return lo

        def sum_bit_pos(n):
            if n <= 0: return 0
            result = 0
            for b in range(50):
                cnt = (n >> (b+1)) * (1 << b) + max(0, (n % (1 << (b+1))) - (1 << b) + 1)
                result += b * cnt
            return result

        def get_partial_sum(num, start_bit_idx, end_bit_idx):
            bits = [b for b in range(50) if (num >> b) & 1]
            return sum(bits[start_bit_idx:end_bit_idx+1])

        ans = []
        for frm, to, mod in queries:
            num_start = find_kth(frm)
            offset_start = frm - count_bits(num_start - 1)
            num_end = find_kth(to)
            offset_end = to - count_bits(num_end - 1)

            if num_start == num_end:
                exp = get_partial_sum(num_start, offset_start, offset_end)
            else:
                bits_start = [b for b in range(50) if (num_start >> b) & 1]
                exp = sum(bits_start[offset_start:])
                exp += sum_bit_pos(num_end - 1) - sum_bit_pos(num_start)
                bits_end = [b for b in range(50) if (num_end >> b) & 1]
                exp += sum(bits_end[:offset_end+1])

            ans.append(pow(2, exp, mod))
        return ans

def main():
    import ast
    data = sys.stdin.read().strip()
    queries = ast.literal_eval(data)
    sol = Solution()
    print(sol.findProductsOfElements(queries))

