MOD = 998244353

def solve():
    S = input().strip()
    # states: 0, 1..26 (state1 with letter 0..25), 27..52 (state2 with letter 0..25), 53 (state3)
    # state 54 = bad

    dp = [0] * 54
    dp[0] = 1

    def get_chars(ch):
        if ch == '?':
            return [(c, True) for c in range(26)] + [(c, False) for c in range(26)]
        elif ch.isupper():
            return [(ord(ch)-ord('A'), True)]
        else:
            return [(ord(ch)-ord('a'), False)]

    for ch in S:
        chars = get_chars(ch)
        new_dp = [0] * 54
        for c, is_upper in chars:
            for s in range(54):
                if dp[s] == 0:
                    continue
                val = dp[s]
                # transition
                if s == 0:
                    ns = (1 + c) if is_upper else 0
                elif 1 <= s <= 26:
                    lc = s - 1
                    if is_upper:
                        ns = 27 + c if lc == c else 1 + c
                    else:
                        ns = s
                elif 27 <= s <= 52:
                    if is_upper:
                        ns = s  # stay
                    else:
                        ns = 53
                else:  # s == 53
                    if is_upper:
                        continue  # bad state, skip
                    else:
                        ns = 53
                new_dp[ns] = (new_dp[ns] + val) % MOD
        dp = new_dp

    print(sum(dp) % MOD)

