class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)

        # Check if already sorted
        if nums == sorted(nums):
            return 0

        # Try each number of right shifts from 1 to n-1
        for shifts in range(1, n):
            # Right shift by 'shifts' means taking last 'shifts' elements and putting them at front
            rotated = nums[n - shifts:] + nums[:n - shifts]
            if rotated == sorted(nums):
                return shifts

        return -1

