class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        s = list(s)

        # Find first non-'a' character
        start = -1
        for i in range(n):
            if s[i] != 'a':
                start = i
                break

        # All 'a's: must perform operation, best is to change last char only
        if start == -1:
            s[-1] = 'z'
            return ''.join(s)

        # Apply operation from start, continuing while non-'a'
        i = start
        while i < n and s[i] != 'a':
            s[i] = chr(ord(s[i]) - 1)
            i += 1

        return ''.join(s)

