from math import inf

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N, M = int(input_data[idx]), int(input_data[idx+1]); idx += 2

    dist = [[inf]*N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    for _ in range(M):
        u, v, w = int(input_data[idx])-1, int(input_data[idx+1])-1, int(input_data[idx+2])
        idx += 3
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall
    for k in range(N):
        for i in range(N):
            if dist[i][k] == inf:
                continue
            for j in range(N):
                if dist[k][j] == inf:
                    continue
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # TSP DP
    full = (1 << N) - 1
    dp = [[inf]*N for _ in range(1 << N)]

    for v in range(N):
        dp[1 << v][v] = 0

    for mask in range(1, 1 << N):
        for v in range(N):
            if dp[mask][v] == inf:
                continue
            if not (mask >> v & 1):
                continue
            for u in range(N):
                if mask >> u & 1:
                    continue
                if dist[v][u] == inf:
                    continue
                new_mask = mask | (1 << u)
                if dp[new_mask][u] > dp[mask][v] + dist[v][u]:
                    dp[new_mask][u] = dp[mask][v] + dist[v][u]

    ans = min(dp[full])
    if ans == inf:
        print("No")
    else:
        print(ans)

solve()

