                idx = i * W + j
                if i + 1 < H and grid[i+1][j] == '#':
                    union(idx, (i+1)*W+j)
                if j + 1 < W and grid[i][j+1] == '#':
                    union(idx, i*W+j+1)

    current_components = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                idx = i * W + j
                if find(idx) == idx:
