from typing import List

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0

        for i in range(n):
            sorted_arr = []
            imbalance = 0
            for j in range(i, n):
                v = nums[j]
                pos = bisect_left(sorted_arr, v)
                has_left = pos > 0
                has_right = pos < len(sorted_arr)

                if (has_left and sorted_arr[pos-1] == v) or (has_right and sorted_arr[pos] == v):
                    insort(sorted_arr, v)
                    total += imbalance
                    continue

                L = sorted_arr[pos-1] if has_left else None
                R = sorted_arr[pos] if has_right else None

                if L is not None and R is not None:
                    if R - L > 1:
                        imbalance -= 1
                    if v - L > 1:
                        imbalance += 1
                    if R - v > 1:
                        imbalance += 1
                elif L is not None:
                    if v - L > 1:
                        imbalance += 1
                elif R is not None:
                    if R - v > 1:
                        imbalance += 1

                insort(sorted_arr, v)
                total += imbalance

        return total

