        n = len(s)

        @lru_cache(maxsize=None)
        def dp(pos, last_digit, tight, started):
            if pos == n:
                return 1 if started else 0

            limit = int(s[pos]) if tight else 9
            result = 0

            for d in range(0, limit + 1):
                if not started:
                    if d == 0:
                        result = (result + dp(pos + 1, -1, tight and (d == limit), False)) % MOD
                    else:
                        result = (result + dp(pos + 1, d, tight and (d == limit), True)) % MOD
                else:
                    if abs(d - last_digit) == 1:
                        result = (result + dp(pos + 1, d, tight and (d == limit), True)) % MOD

            return result

        res = dp(0, -1, True, False)
        dp.cache_clear()
        return res

    def subtract_one(s):
        s = list(s)
        i = len(s) - 1
        while i >= 0 and s[i] == '0':
