from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x <= y:
            return y - x

        # BFS from x to y
        visited = {x}
        queue = deque([(x, 0)])

        while queue:
            curr, ops = queue.popleft()

            if curr == y:
                return ops

            # Generate next states
            nexts = []

            # Decrement
            if curr - 1 >= y:
                nexts.append(curr - 1)
            else:
                nexts.append(y)  # direct jump

            # Increment
            nexts.append(curr + 1)

            # Divide by 5
            if curr % 5 == 0:
                nexts.append(curr // 5)

            # Divide by 11
            if curr % 11 == 0:
                nexts.append(curr // 11)

            for nxt in nexts:
                if nxt not in visited:
                    if nxt == y:
                        return ops + 1
                    visited.add(nxt)
                    queue.append((nxt, ops + 1))

        return -1

