from functools import lru_cache

class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        n = len(prices)

        @lru_cache(maxsize=None)
        def dp(i):
            # i is 1-indexed: minimum cost to acquire all fruits from i to n
            if i > n:
                return 0
            # We must purchase fruit i
            # After purchasing fruit i, we can get fruits i+1 to i+i for free
            # So next fruit we need to consider purchasing is from i+1 to 2*i+1
            cost = prices[i-1] + min(dp(j) for j in range(i+1, 2*i+2))
            return cost

        return dp(1)

