class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        # Precompute powers of 5 in binary
        powers_of_5 = set()
        val = 1
        while val <= 2**15:
            powers_of_5.add(bin(val)[2:])
            val *= 5

        n = len(s)

        @lru_cache(maxsize=None)
        def dp(i):
            if i == n:
                return 0
            if s[i] == '0':
                return float('inf')
            res = float('inf')
            for j in range(i+1, n+1):
                substr = s[i:j]
                if substr in powers_of_5:
                    sub_res = dp(j)
                    if sub_res != float('inf'):
                        res = min(res, 1 + sub_res)
            return res

        result = dp(0)
        return result if result != float('inf') else -1

