class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s, target):
            if not s:
                return target == 0
            for i in range(1, len(s) + 1):
                val = int(s[:i])
                if val <= target and can_partition(s[i:], target - val):
                    return True
            return False

        result = 0
        for i in range(1, n + 1):
            sq = i * i
            if can_partition(str(sq), i):
                result += sq
        return result

