class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        freq = Counter()
        for w in words:
            freq.update(w)
        pairs = sum(v // 2 for v in freq.values())
        singles = sum(v % 2 for v in freq.values())
        lengths = sorted(len(w) for w in words)
        count = 0
        for l in lengths:
            needed_pairs = l // 2
            if pairs >= needed_pairs:
                pairs -= needed_pairs
                if l % 2 == 1:
                    if singles > 0:
                        singles -= 1
                    elif pairs > 0:
                        pairs -= 1
                        singles += 1
                    else:
                        break
                count += 1
            else:
                break
        return count

