class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def square_free(n):
            result = 1
            d = 2
            while d * d <= n:
                count = 0
                while n % d == 0:
                    n //= d
                    count += 1
                if count % 2 == 1:
                    result *= d
                d += 1
            if n > 1:
                result *= n
            return result

        groups = defaultdict(int)
        for i, val in enumerate(nums):
            idx = i + 1  # 1-indexed
            sf = square_free(idx)
            groups[sf] += val

        return max(groups.values())

