        if row == N:
            for j in range(N):
                if col_count[j][0] != 1 or col_count[j][1] != 1 or col_count[j][2] != 1:
                    return False
                if col_top[j] != C[j]:
                    return False
            return True

        for cols in permutations(range(N), 3):
            ca, cb, cc = cols
            if col_count[ca][0] >= 1: continue
            if col_count[cb][1] >= 1: continue
            if col_count[cc][2] >= 1: continue

            chars = {ca:'A', cb:'B', cc:'C'}
            leftmost_col = min(ca, cb, cc)
            leftmost_char = chars[leftmost_col]
            if leftmost_char != R[row]: continue

            valid = True
            for col, ch in [(ca,'A'),(cb,'B'),(cc,'C')]:
                if col_top[col] is None:
                    if ch != C[col]:
                        valid = False
                        break
            if not valid: continue

            grid[row][ca] = 'A'; grid[row][cb] = 'B'; grid[row][cc] = 'C'
            col_count[ca][0] += 1; col_count[cb][1] += 1; col_count[cc][2] += 1
            old_tops = {}
            for col, ch in [(ca,'A'),(cb,'B'),(cc,'C')]:
                if col_top[col] is None:
                    col_top[col] = ch
                    old_tops[col] = None

            if backtrack(row + 1):
                return True

            grid[row][ca] = '.'; grid[row][cb] = '.'; grid[row][cc] = '.'
            col_count[ca][0] -= 1; col_count[cb][1] -= 1; col_count[cc][2] -= 1
            for col in old_tops:
