import sys
from functools import lru_cache

class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def count_up_to(num_str):
            if not num_str or num_str == '0':
                return 0
            n = len(num_str)
            digits = [int(c) for c in num_str]

            @lru_cache(maxsize=None)
            def dp(pos, curr_sum, tight, started):
                if curr_sum > max_sum:
                    return 0
                if pos == n:
                    if not started:
                        return 0
                    return 1 if min_sum <= curr_sum <= max_sum else 0

                limit = digits[pos] if tight else 9
                result = 0
                for d in range(0, limit + 1):
                    if not started and d == 0:
                        result += dp(pos + 1, 0, tight and (d == limit), False)
                    else:
                        result += dp(pos + 1, curr_sum + d, tight and (d == limit), True)
                return result % MOD

            ans = dp(0, 0, True, False)
            dp.cache_clear()
            return ans

        def subtract_one(num_str):
            s = list(num_str)
            i = len(s) - 1
            while i >= 0 and s[i] == '0':
                s[i] = '9'
                i -= 1
            if i < 0:
                return '0'
            s[i] = str(int(s[i]) - 1)
            result = ''.join(s).lstrip('0')
            return result if result else '0'

        ans = (count_up_to(num2) - count_up_to(subtract_one(num1))) % MOD
        return ans

