import sys
from itertools import combinations

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx += 1
    M = int(input_data[idx]); idx += 1
    K = int(input_data[idx]); idx += 1

    edges = []
    for i in range(M):
        u = int(input_data[idx]); idx += 1
        v = int(input_data[idx]); idx += 1
        w = int(input_data[idx]); idx += 1
        edges.append((u, v, w))

    def find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(parent, rank, x, y):
        rx, ry = find(parent, x), find(parent, y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    def is_spanning_tree(edge_indices):
        parent = list(range(N + 1))
        rank = [0] * (N + 1)
        for i in edge_indices:
            u, v, w = edges[i]
            if not union(parent, rank, u, v):
                return False
        return True

    min_cost = float('inf')

    for combo in combinations(range(M), N - 1):
        if is_spanning_tree(combo):
            total = sum(edges[i][2] for i in combo) % K
            if total < min_cost:
                min_cost = total

    print(min_cost)

